#include <map>
#include <utility>

using namespace std;

typedef pair<int, int> pii;

int n;
vector<string> a;
vector<map<char, int> > b(1);

void rec(int x, int y, int bp) {
    char c = a[x][y];
    map<char, int>::iterator it = b[bp].find(c);

    if (it == b[bp].end()) {
        int next = static_cast<int>(b.size());
        b.push_back(map<char, int>());
        b[bp][c] = next;
        it = b[bp].find(c);
    }

    int next = it->second;

    if (x + 1 < n)
        rec(x + 1, y, next);
    if (y + 1 < n)
        rec(x, y + 1, next);
}

pii doit(int bp, int mark) {
    int q = -1;
    pii w(0, 0);

    for (map<char, int>::const_iterator it = b[bp].begin();
         it != b[bp].end(); ++it) {
        char c = it->first;
        pii tmp = doit(it->second, mark ^ 1);

        if (c == 'a')
            ++tmp.first;
        if (c == 'b')
            ++tmp.second;

        bool res = mark ? (tmp.second > q) : (tmp.first > q);

        if (res) {
            q = mark ? tmp.second : tmp.first;
            w = tmp;
        }
    }

    return w;
}

