}

#include <iostream>
#include <string>
#include <vector>
#include <deque>
#include <utility>

using namespace std;

using pii = pair<int, int>;

struct Node {
    int firstChild;
    int nextSibling;
    char label;
};

int n;
vector<string> board;
deque<Node> trie(1, {-1, -1, 0});

int getChild(int parent, char label) {
    for (int child = trie[parent].firstChild;
         child != -1;
         child = trie[child].nextSibling) {
        if (trie[child].label == label)
            return child;
    }

    int child = static_cast<int>(trie.size());
    int sibling = trie[parent].firstChild;
    trie.push_back({-1, sibling, label});
    trie[parent].firstChild = child;
    return child;
}

void rec(int x, int y, int node) {
    int child = getChild(node, board[x][y]);

    if (x + 1 < n)
        rec(x + 1, y, child);
    if (y + 1 < n)
        rec(x, y + 1, child);
}

pii doit(int node, int mark) {
    int best = -1;
    pii result = {0, 0};
    vector<int> children(26, -1);

    for (int child = trie[node].firstChild;
         child != -1;
         child = trie[child].nextSibling) {
        char c = trie[child].label;
        if (c >= 'a' && c <= 'z')
            children[c - 'a'] = child;
    }

    for (char c = 'a'; c <= 'z'; ++c) {
        int child = children[c - 'a'];
        if (child == -1)
            continue;

        pii current = doit(child, mark ^ 1);

        if (c == 'a')
            ++current.first;
        if (c == 'b')
            ++current.second;

        int score = mark ? current.second : current.first;
        if (score > best) {
            best = score;
            result = current;
        }
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    board.resize(n);

    for (int i = 0; i < n; ++i)
        cin >> board[i];

    if (n <= 0)
        return 0;

    rec(0, 0, 0);

    pii result = doit(0, 0);

    if (result.first < result.second)
        cout << "SECOND";
    else if (result.first > result.second)
        cout << "FIRST";
    else
        cout << "DRAW";

    return 0;
}

