#include <utility>

using namespace std;

struct Node {
    int head = -1;
};

struct Edge {
    int to;
    int next;
    char ch;
};

int n;
vector<string> grid;
vector<Node> nodes(1);
vector<Edge> edges;
unordered_set<uint64_t> visited;

int getChild(int node, char ch) {
    for (int e = nodes[node].head; e != -1; e = edges[e].next) {
        if (edges[e].ch == ch)
            return edges[e].to;
    }

    int head = nodes[node].head;
    int child = static_cast<int>(nodes.size());
    nodes.push_back(Node{});
    edges.push_back({child, head, ch});
    nodes[node].head = static_cast<int>(edges.size()) - 1;
    return child;
}

void rec(int x, int y, int parent) {
    uint64_t key = (static_cast<uint64_t>(parent) << 12)
                 | (static_cast<uint64_t>(x) << 6)
                 | static_cast<uint64_t>(y);

    if (!visited.insert(key).second)
        return;

    int child = getChild(parent, grid[x][y]);

    if (x + 1 < n)
        rec(x + 1, y, child);
    if (y + 1 < n)
        rec(x, y + 1, child);
}

pair<int, int> doit(int node, bool mark) {
    int children[26] = {};

    for (int e = nodes[node].head; e != -1; e = edges[e].next) {
        char ch = edges[e].ch;
        if (ch >= 'a' && ch <= 'z')
            children[ch - 'a'] = edges[e].to;
    }

    int best = -1;
    pair<int, int> result{0, 0};

    for (int i = 0; i < 26; ++i) {
        if (children[i] == 0)
            continue;

        pair<int, int> current = doit(children[i], !mark);

        if (i == 0)
            ++current.first;
        else if (i == 1)
            ++current.second;

        int score = mark ? current.second : current.first;
        if (score > best) {
            best = score;
            result = current;
        }
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    grid.resize(n);

    for (int i = 0; i < n; ++i)
        cin >> grid[i];

    if (n > 0)
        rec(0, 0, 0);

    pair<int, int> result = doit(0, false);

    if (result.first < result.second)
        cout << "SECOND";
    else if (result.first > result.second)
        cout << "FIRST";
    else
        cout << "DRAW";

    return 0;
}

